#include <knowledge/graph.hpp>
namespace rebuntu::knowledge { void Graph::relate(Edge e){edges_.emplace(e.from,std::move(e));} std::vector<Edge> Graph::outgoing(const std::string&n)const{std::vector<Edge>o;auto [b,e]=edges_.equal_range(n);for(;b!=e;++b)o.push_back(b->second);return o;} std::set<std::string> Graph::reachable(const std::string&n,std::size_t depth)const{std::set<std::string>seen{n},front{n};for(size_t d=0;d<depth&&!front.empty();++d){std::set<std::string>next;for(auto&x:front)for(auto&e:outgoing(x))if(seen.insert(e.to).second)next.insert(e.to);front=std::move(next);}seen.erase(n);return seen;} }
